<?php
if (!defined('KFX_API_INTERNAL')) { http_response_code(404); exit; }
trait HubCommunity {
    private function communityWrite(string $route,array $parts,array $data,string $token,?string $uid): ?array {
        if(count($parts)===4&&$parts[1]==='matches'&&$parts[3]==='result'){
            $mid=$parts[2];$row=$this->one('SELECT * FROM matches WHERE id=?',[$mid]);demand($row,'Match not found',404);$result=$data['result']??null;demand(in_array($result,['won','lost','draw','disconnected'],true),'Invalid result');demand($uid,'Sign in first',401);demand($this->one('SELECT 1 FROM participants WHERE match=? AND user=?',[$mid,$uid]),'Not a match participant',403);demand(!$row['ended'],'Match is already closed',409);$this->q('UPDATE participants SET result=? WHERE match=? AND user=?',[$result,$mid,$uid]);$results=$this->rows('SELECT * FROM participants WHERE match=?',[$mid]);$server=$this->one('SELECT kind FROM servers WHERE id=?',[$row['server']]);if($results&&count(array_filter($results,fn($r)=>$r['result']===''))===0&&($server['kind']??'')!=='dedicated'){$winners=array_values(array_filter($results,fn($r)=>$r['result']==='won'));$consistent=count($winners)===1&&count(array_filter($results,fn($r)=>!in_array($r['result'],['won','lost'],true)))===0;$this->q("UPDATE matches SET ended=?,winner=?,verification=?,status='finished' WHERE id=?",[$this->now,count($winners)===1?$winners[0]['user']:'',$consistent?'confirmed':'casual',$mid]);}return ['ok'=>true,'verification'=>'client-reported'];
        }
        if($route==='/api/events'){demand($uid,'Sign in first',401);$title=api_text($data['title']??null,80);$kind=$data['kind']??'match';demand(in_array($kind,['match','tournament','cooperative'],true),'Invalid event type');$starts=$data['starts']??null;demand((is_int($starts)||is_float($starts))&&is_finite((float)$starts)&&$starts>=$this->now&&$starts<=$this->now+366*86400,'Invalid event time');$id=bin2hex(random_bytes(12));$this->q('INSERT INTO events VALUES(?,?,?,?,?,?)',[$id,$uid,$title,$kind,$starts,mb_substr($data['description']??'',0,1000)]);return ['id'=>$id];}
        if(count($parts)===4&&$parts[1]==='events'&&$parts[3]==='join'){demand($uid,'Sign in first',401);demand($this->one('SELECT 1 FROM events WHERE id=?',[$parts[2]]),'Event not found',404);demand(!$this->one('SELECT 1 FROM bracket WHERE event=?',[$parts[2]]),'Tournament registration has closed',409);$this->q('INSERT OR IGNORE INTO entrants VALUES(?,?)',[$parts[2],$uid]);return ['ok'=>true];}
        if(count($parts)===5&&$parts[1]==='events'&&$parts[3]==='bracket')return $this->bracketWrite($parts[2],$parts[4],$data,$uid);
        if(count($parts)===4&&$parts[1]==='challenges'&&$parts[3]==='complete'){demand($uid,'Sign in first',401);$challenge=$this->one('SELECT * FROM challenges WHERE id=?',[$parts[2]]);demand($challenge,'Challenge not found',404);$match=$this->one("SELECT m.* FROM matches m JOIN participants p ON p.match=m.id WHERE m.id=? AND p.user=? AND p.result='won' AND m.verification='verified'",[$data['match']??null,$uid]);demand($match&&$match['map']===$challenge['map'],'Use a verified win on this challenge map',409);$this->q('INSERT OR IGNORE INTO completions VALUES(?,?,?)',[$uid,$parts[2],$match['id']]);return ['ok'=>true];}
        if($route==='/api/challenges'){demand($this->admin!==''&&hash_equals($this->admin,$token),'Administrator credential required',403);$id=bin2hex(random_bytes(12));$this->q('INSERT INTO challenges VALUES(?,?,?,?)',[$id,api_text($data['title']??null,80),api_text($data['map']??null,80),api_text($data['description']??null,1000)]);return ['id'=>$id];}
        if($route==='/api/replays'){demand($uid,'Sign in first',401);$mid=api_text($data['match']??null,32);$row=$this->one('SELECT m.* FROM matches m JOIN participants p ON p.match=m.id WHERE m.id=? AND p.user=?',[$mid,$uid]);demand($row&&$row['ended'],'Only participants can upload completed-match replays',403);demand(is_string($data['data']??null),'Invalid replay encoding');$raw=base64_decode($data['data'],true);demand($raw!==false,'Invalid replay encoding');demand(strlen($raw)>0&&strlen($raw)<=2*1024*1024,'Replay limit is 2 MiB');$id=bin2hex(random_bytes(16));$this->storeReplay($id,$mid,$uid,$raw);return ['id'=>$id,'sha256'=>hash('sha256',$raw)];}
        return null;
    }
    private function bracketRead(string $id): array {
        $games=$this->rows('SELECT * FROM bracket WHERE event=? ORDER BY round,position',[$id]);if($games){foreach($games as &$game)foreach(['a','b','winner'] as $role)$game[$role.'_name']=$this->one('SELECT name FROM users WHERE id=?',[$game[$role]])['name']??'Bye';unset($game);$last=$games[count($games)-1];return ['games'=>$games,'champion'=>in_array($last['status'],['played','bye'],true)?$last['winner']:''];}
        $rows=$this->rows('SELECT u.id,u.name FROM entrants e JOIN users u ON u.id=e.user WHERE event=? ORDER BY u.id',[$id]);$round=[];for($i=0;$i<count($rows);$i+=2)$round[]=['a'=>$rows[$i],'b'=>$rows[$i+1]??null];return ['round_one'=>$round];
    }
    private function bracketWrite(string $id,string $action,array $data,?string $uid): array {
        demand($uid,'Sign in first',401);$event=$this->one('SELECT * FROM events WHERE id=?',[$id]);demand($event&&$event['owner']===$uid&&$event['kind']==='tournament','Tournament organizer required',403);
        if($action==='start'){
            demand(!$this->one('SELECT 1 FROM bracket WHERE event=?',[$id]),'Bracket already started',409);$entrants=array_column($this->rows('SELECT user FROM entrants WHERE event=?',[$id]),'user');demand(count($entrants)>=2&&count($entrants)<=32,'A bracket needs 2–32 entrants');for($i=count($entrants)-1;$i>0;$i--){$j=random_int(0,$i);[$entrants[$i],$entrants[$j]]=[$entrants[$j],$entrants[$i]];}$width=1;while($width<count($entrants))$width*=2;$entrants=array_pad($entrants,$width,'');$round=1;for($count=intdiv($width,2);$count>0;$count=intdiv($count,2),$round++){for($pos=0;$pos<$count;$pos++){$a=$round===1?$entrants[$pos]:'';$b=$round===1?$entrants[$width-$pos-1]:'';$bye=$round===1&&($a===''||$b==='');$this->q('INSERT INTO bracket VALUES(?,?,?,?,?,?,NULL,?)',[$id,$round,$pos,$a,$b,$bye?($a?:$b):'',$bye?'bye':($round===1?'pending':'waiting')]);}}
        }elseif($action==='report'){
            $round=$data['round']??null;$pos=$data['position']??null;demand(is_int($round)&&is_int($pos),'Choose a bracket game');$game=$this->one('SELECT * FROM bracket WHERE event=? AND round=? AND position=?',[$id,$round,$pos]);demand($game&&$game['status']==='pending','Bracket game is not ready',409);$match=$this->one("SELECT * FROM matches WHERE id=? AND verification='verified'",[$data['match']??null]);demand($match&&in_array($match['winner'],[$game['a'],$game['b']],true),'Choose a verified match won by this pairing',409);$players=array_column($this->rows('SELECT user FROM identities WHERE match=?',[$match['id']]),'user');sort($players);$expected=[$game['a'],$game['b']];sort($expected);demand($players===$expected,'Verified players differ from the bracket',409);demand(!$this->one('SELECT 1 FROM bracket WHERE match=?',[$match['id']]),'Match already used in a bracket',409);$this->q("UPDATE bracket SET winner=?,match=?,status='played' WHERE event=? AND round=? AND position=?",[$match['winner'],$match['id'],$id,$round,$pos]);
        }else throw new ApiProblem(404,'Not found');
        foreach($this->rows("SELECT * FROM bracket WHERE event=? AND status='waiting' ORDER BY round,position",[$id]) as $game){$parents=$this->rows('SELECT * FROM bracket WHERE event=? AND round=? AND position IN (?,?) ORDER BY position',[$id,$game['round']-1,$game['position']*2,$game['position']*2+1]);if(count($parents)===2&&in_array($parents[0]['status'],['played','bye'],true)&&in_array($parents[1]['status'],['played','bye'],true)){$a=$parents[0]['winner'];$b=$parents[1]['winner'];$bye=$a===''||$b==='';$this->q('UPDATE bracket SET a=?,b=?,winner=?,status=? WHERE event=? AND round=? AND position=?',[$a,$b,$bye?($a?:$b):'',$bye?'bye':'pending',$id,$game['round'],$game['position']]);}}
        return ['ok'=>true];
    }
}
